/**
 * A represa do castor — porte de `componentes/viz/castor.js`.
 *
 * O castor não empilha gravetos numa linha reta: ele CURVA a represa contra a
 * correnteza. O arco joga a pressão da água para as margens em vez de concentrá-la
 * no meio — é o mesmo princípio das barragens em arco que os engenheiros
 * projetam. Reta demais, a pressão se junta no centro e arromba.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  type EstadoDaViz,
  infoDe,
  MATERIAIS,
  numeroDe,
  paleta,
  rodape,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

const castor: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    const curvatura = Math.max(0, numeroDe(valores, 'c', 0));
    const ok = info.ok === true;
    const arco = (curvatura / 100) * (L * 0.26);
    const damX = L * 0.56;
    const rompe = curvatura < numeroDe(info, 'alvoMin', 45);

    titulo(ctx, L, A, 'O arco que joga a força para as margens');

    // O lago represado.
    ctx.fillStyle = rompe ? 'rgb(60 110 150 / 55%)' : 'rgb(46 120 170 / 75%)';
    ctx.beginPath();
    ctx.moveTo(0, A * 0.3);
    ctx.lineTo(damX, A * 0.3);
    ctx.quadraticCurveTo(damX - arco, A * 0.58, damX, A * 0.86);
    ctx.lineTo(0, A * 0.86);
    ctx.closePath();
    ctx.fill();

    ctx.strokeStyle = cor.contraste;
    ctx.globalAlpha = 0.45;
    ctx.lineWidth = 1;
    for (let i = 0; i < 3; i++) {
      const y = A * 0.36 + i * 10;
      ctx.beginPath();
      for (let x = 0; x < damX - arco * 0.5; x += 8) {
        const yy = y + Math.sin(x * 0.08 + t * 1.5 + i) * 1.6;
        if (x === 0) ctx.moveTo(x, yy);
        else ctx.lineTo(x, yy);
      }
      ctx.stroke();
    }
    ctx.globalAlpha = 1;

    // As setas de pressão. Na represa reta elas se juntam no meio — que é
    // exatamente onde ela arromba.
    ctx.strokeStyle = rompe ? cor.erro : cor.azulClaro;
    ctx.lineWidth = 2;
    ctx.lineCap = 'round';
    for (let i = 0; i < 5; i++) {
      const y = A * 0.37 + i * ((A * 0.46) / 4);
      const meio = 1 - Math.abs(i - 2) / 2;
      const comprimento = 10 + meio * (rompe ? 22 : 10);
      const x = damX - arco * meio - 26;

      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(x + comprimento, y);
      ctx.moveTo(x + comprimento, y);
      ctx.lineTo(x + comprimento - 4, y - 3);
      ctx.moveTo(x + comprimento, y);
      ctx.lineTo(x + comprimento - 4, y + 3);
      ctx.stroke();
    }

    // A represa de gravetos.
    ctx.strokeStyle = rompe ? cor.erro : MATERIAIS.madeira;
    ctx.lineWidth = 8;
    ctx.beginPath();
    ctx.moveTo(damX, A * 0.3);
    ctx.quadraticCurveTo(damX - arco, A * 0.58, damX, A * 0.86);
    ctx.stroke();

    ctx.strokeStyle = MATERIAIS.madeiraClara;
    ctx.lineWidth = 1.5;
    for (let s = 0.1; s < 1; s += 0.18) {
      const yy = A * 0.3 + s * A * 0.56;
      const xx = damX - arco * Math.sin(s * Math.PI);
      ctx.beginPath();
      ctx.moveTo(xx - 9, yy);
      ctx.lineTo(xx + 9, yy);
      ctx.stroke();
    }

    if (rompe) {
      ctx.fillStyle = cor.azulClaro;
      for (let i = 0; i < 6; i++) {
        const fase = (t * 1.2 + i / 6) % 1;
        ctx.beginPath();
        ctx.arc(damX + fase * L * 0.3, A * 0.58 + Math.sin(i) * 10 + fase * 20, 3, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    rodape(
      ctx,
      L,
      A,
      ok,
      'Arco firme: a represa segura o lago ✔',
      rompe ? 'A pressão arrombou a represa reta.' : 'Ajuste a curvatura do arco.',
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => desenhar(ctx, L, A, t),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default castor;
